import React, { useEffect, useState } from 'react';
import axios from 'axios';

function App() {
  const [productos, setProductos] = useState([]);
  const [nuevoProducto, setNuevoProducto] = useState({
    nombre: '', categoria: '', precio: '', stockActual: ''
  });

  useEffect(() => {
    obtenerProductos();
  }, []);

  const obtenerProductos = async () => {
    try {
      const respuesta = await axios.get('http://localhost:8080/api/productos');
      setProductos(respuesta.data);
    } catch (error) {
      console.error("Error al obtener productos:", error);
    }
  };

  const manejarCambio = (e) => {
    setNuevoProducto({ ...nuevoProducto, [e.target.name]: e.target.value });
  };

  const guardarProducto = async (e) => {
    e.preventDefault();
    try {
      await axios.post('http://localhost:8080/api/productos', nuevoProducto);
      setNuevoProducto({ nombre: '', categoria: '', precio: '', stockActual: '' });
      obtenerProductos();
    } catch (error) {
      alert("Hubo un error al conectar con la cafetera (el servidor).");
    }
  };

  // --- ESTILOS PROPIOS (Cafetería Style) ---
  const estilos = {
    contenedor: {
      backgroundColor: '#fdfaf6',
      minHeight: '100vh',
      padding: '40px',
      fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
      color: '#4b3832'
    },
    encabezado: {
      textAlign: 'center',
      borderBottom: '3px solid #d4a373',
      paddingBottom: '20px',
      marginBottom: '40px'
    },
    formulario: {
      backgroundColor: '#fff',
      padding: '25px',
      borderRadius: '12px',
      boxShadow: '0 4px 15px rgba(0,0,0,0.1)',
      maxWidth: '800px',
      margin: '0 auto 50px auto'
    },
    input: {
      padding: '12px',
      margin: '8px',
      borderRadius: '6px',
      border: '1px solid #d4a373',
      width: '180px'
    },
    boton: {
      backgroundColor: '#3e5622',
      color: 'white',
      padding: '12px 25px',
      border: 'none',
      borderRadius: '6px',
      cursor: 'pointer',
      fontWeight: 'bold',
      transition: '0.3s'
    },
    tabla: {
      width: '100%',
      backgroundColor: 'white',
      borderRadius: '12px',
      overflow: 'hidden',
      boxShadow: '0 4px 15px rgba(0,0,0,0.05)',
      borderCollapse: 'collapse'
    },
    th: {
      backgroundColor: '#4b3832',
      color: '#fff',
      padding: '15px',
      textAlign: 'left'
    },
    td: {
      padding: '15px',
      borderBottom: '1px solid #eee'
    },
    alertaStock: {
      color: '#d9534f',
      fontWeight: 'bold'
    }
  };

  return (
    <div style={estilos.contenedor}>
      <header style={estilos.encabezado}>
        <h1 style={{fontSize: '3rem', margin: 0}}>☕ El Paisita UP</h1>
        <p style={{fontStyle: 'italic'}}>Administración de Inventario y Ventas</p>
      </header>

      <section style={estilos.formulario}>
        <h3 style={{marginTop: 0, color: '#6f4e37'}}>Añadir Nuevo Suministro</h3>
        <form onSubmit={guardarProducto} style={{display: 'flex', flexWrap: 'wrap', justifyContent: 'center'}}>
          <input name="nombre" placeholder="Producto (ej: Cappuccino)" value={nuevoProducto.nombre} onChange={manejarCambio} required style={estilos.input} />
          <input name="categoria" placeholder="Categoría (ej: Bebidas)" value={nuevoProducto.categoria} onChange={manejarCambio} required style={estilos.input} />
          <input name="precio" type="number" placeholder="Precio ($)" value={nuevoProducto.precio} onChange={manejarCambio} required style={estilos.input} />
          <input name="stockActual" type="number" placeholder="Stock" value={nuevoProducto.stockActual} onChange={manejarCambio} required style={estilos.input} />
          <button type="submit" style={estilos.boton}>Agregar al Menú</button>
        </form>
      </section>

      <section style={{maxWidth: '1000px', margin: '0 auto'}}>
        <table style={estilos.tabla}>
          <thead>
            <tr>
              <th style={estilos.th}>Producto</th>
              <th style={estilos.th}>Categoría</th>
              <th style={estilos.th}>Precio Unitario</th>
              <th style={estilos.th}>Inventario Actual</th>
            </tr>
          </thead>
          <tbody>
            {productos.map((prod) => (
              <tr key={prod.id}>
                <td style={estilos.td}>{prod.nombre}</td>
                <td style={estilos.td}>{prod.categoria}</td>
                <td style={estilos.td}>${prod.precio.toLocaleString()}</td>
                <td style={{...estilos.td, ...(prod.stockActual < 5 ? estilos.alertaStock : {})}}>
                  {prod.stockActual} unidades {prod.stockActual < 5 && '⚠️ (Bajo)'}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>
    </div>
  );
}

export default App;
